import java.io.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;
public class VerifyHook {public static void main(String[] args)throws Exception {var dex=DexFileFactory.loadDexFile(new File(args[0]),Opcodes.forDexVersion(39));for(ClassDef c:dex.getClasses())if(c.getType().equals("Lcom/n810/camera/lab/Compatibility;"))for(Method m:c.getMethods())if(m.getName().equals("beforePreview")){int n=0;String[] expected={"CameraConfigTiming;->awaitStreams()V","CameraMetadataTest;->apply()V"};for(Instruction i:m.getImplementation().getInstructions()){if(n<2){if(!(i instanceof ReferenceInstruction))throw new Exception("Missing startup invoke");String ref=((ReferenceInstruction)i).getReference().toString();if(!ref.endsWith(expected[n]))throw new Exception(ref);System.out.println(ref);}n++;}System.out.println("Verified bounded metadata hook follows existing configuration wait.");return;}throw new Exception("Hook not found");}}
